#include<bits/stdc++.h>
#define int long long
using namespace std;
int c[2222][2222];
int mod=1e9+7;
int f(int a,int b){
    if (b==0){
        return 1;
    }
    int h=f(a,b/2);
    int x=(h*h)%mod;
    if (b%2==1) {
        x=(x*a)%mod;
	}
    return x; 
}
void akioi(){
	int n,m,k;
	cin>>n>>m>>k;
	if(m<2*k){
		cout<<0<<endl;
		return ;
	}
	cout<<((c[n][k]*c[n-k][m-2*k])%mod*f(2,m-2*k))%mod<<endl;
}
signed main(){
	c[0][0]=1;
	for(int i=1;i<=2005;i++){
		c[i][0]=1;
	}
	for(int i=1;i<=2005;i++){
		for(int j=1;j<=2005;j++){
			c[i][j]=(c[i-1][j-1]+c[i-1][j])%mod;
		}
	}
	int t;
	cin>>t;
	while(t--){
		akioi();
	}
	return 0;
}
